const test = require('node:test');
const assert = require('node:assert/strict');
const {evaluateReview,run,BOT_ID,APP_ID} = require('../scripts/review-gate.cjs');
const HEAD='a'.repeat(40);
function comment(metadata, extra={}) {return {user:{id:BOT_ID,type:'Bot'},performed_via_github_app:{id:APP_ID},body:'<!-- codex-review-state:v1 '+JSON.stringify(metadata)+' -->',updated_at:'2026-11-21T00:00:00Z',html_url:'https://github.com/example/repo/pull/1#issuecomment-1',...extra};}
function meta(extra={}) {return {code_review:{commit_sha:HEAD,status:'completed',has_any_findings:false,has_unresolved_findings:false,...extra},security_review:{commit_sha:HEAD,status:'completed',has_unresolved_findings:null}};}
test('completed trusted review of the exact revision succeeds',()=>assert.equal(evaluateReview([comment(meta())],HEAD).state,'success'));
test('a review of another revision cannot approve the current one',()=>assert.equal(evaluateReview([comment(meta({commit_sha:'b'.repeat(40)}))],HEAD).state,'pending'));
test('unresolved code findings fail the gate',()=>assert.equal(evaluateReview([comment(meta({has_any_findings:true,has_unresolved_findings:true}))],HEAD).state,'failure'));
test('missing or unfinished review remains pending',()=>{assert.equal(evaluateReview([],HEAD).state,'pending');assert.equal(evaluateReview([comment(meta({status:'running'}))],HEAD).state,'pending');assert.equal(evaluateReview([comment(meta({has_unresolved_findings:null}))],HEAD).state,'pending');});
test('a copied marker from a person or another app cannot approve',()=>{assert.equal(evaluateReview([comment(meta(),{user:{id:1,type:'User'}})],HEAD).state,'pending');assert.equal(evaluateReview([comment(meta(),{performed_via_github_app:{id:1}})],HEAD).state,'pending');});
test('malformed comment data is ignored without execution',()=>assert.equal(evaluateReview([comment(meta(),{body:'<!-- codex-review-state:v1 {broken} -->'})],HEAD).state,'pending'));
test('an unfinished or stale security review remains pending',()=>{for(const changes of [{status:'running'},{commit_sha:'b'.repeat(40)}]){const m=meta();Object.assign(m.security_review,changes);assert.equal(evaluateReview([comment(m)],HEAD).state,'pending');}});
test('unresolved security findings fail the gate',()=>{const m=meta();m.security_review.has_unresolved_findings=true;assert.equal(evaluateReview([comment(m)],HEAD).state,'failure');});
test('latest trusted state takes precedence over an earlier success',()=>{const later=comment(meta({status:'running'}),{updated_at:'2026-11-22T00:00:00Z'});assert.equal(evaluateReview([comment(meta()),later],HEAD).state,'pending');});
test('a revision change during API reads cannot publish stale approval',async()=>{let reads=0,writes=0;const github={rest:{pulls:{get:async()=>({data:{number:1,state:'open',draft:false,head:{sha:++reads===1?HEAD:'b'.repeat(40)},base:{ref:'main'},html_url:'https://github.com/example/repo/pull/1'}})},repos:{get:async()=>({data:{default_branch:'main'}}),createCommitStatus:async()=>writes++},issues:{listComments:()=>{}}},paginate:async()=>[comment(meta())]};const core={info:()=>{},summary:{addHeading(){return this},addRaw(){return this},async write(){}}};await run({github,context:{repo:{owner:'example',repo:'repo'},payload:{pull_request:{number:1}}},core});assert.equal(writes,0);});
